Now install the movement probe: sample every 60ms; per NPC track tile changes (x,y landings) and compute inter-transition intervals; also capture aim events with spell+color. Run ~10s of combat, then read results.

Note: page needs to run ~10s. Use background sleep again? Better: install probe, then do other work (screenshot verification of reticle colors while combat runs), then read probe.

Probe:
```js
(function(){
  if (window.__probe) return 'already';
  window.__probe = { last: {}, gaps: {}, aims: [], start: performance.now() };
  setInterval(function(){
    var d = window.AO_DEBUG && window.AO_DEBUG(); if (!d) return;
    d.fighters.forEach(function(f){
      if (f.id === 'player') return;
      var prev = window.__probe.last[f.id];
      if (prev) {
        if ((f.x !== prev.x || f.y !== prev.y) && f.alive) {
          var gap = performance.now() - prev.t;
          (window.__probe.gaps[f.id] = window.__probe.gaps[f.id] || []).push(Math.round(gap));
        }
        if (f.aiming && (!prev.aiming || f.aimSpell !== prev.aimSpell)) window.__probe.aims.push({ t: +((performance.now()-window.__probe.start)/1000).toFixed(1), id: f.id, spell: f.aimSpell, color: f.aimColor });
      }
      window.__probe.last[f.id] = { x: f.x, y: f.y, t: performance.now(), aiming: f.aiming, aimSpell: f.aimSpell };
    });
  }, 60);
  return 'probe installed';
})()

